using System;using System.Collections.Generic;using System.Drawing;using System.Drawing.Drawing2D;using System.Linq;using System.Windows.Forms;
namespace IDSketcher {
partial class VectorShape {
 public bool CanSimplify{get{return (Kind=="Line"||Kind=="Curvature pen")&&Points.Count>2;}}
 public VectorShape Simplified(int reduction){var copy=Copy();if(!CanSimplify)return copy;int target=Math.Max(2,(int)Math.Ceiling(Points.Count*(100-Math.Max(10,Math.Min(90,reduction)))/100.0));List<PointF> samples;using(var path=Path()){path.Flatten(null,.35f);samples=path.PathPoints.ToList();}if(samples.Count<2)return copy;float high=Math.Max(1,StrokeSession.Distance(new PointF(samples.Min(p=>p.X),samples.Min(p=>p.Y)),new PointF(samples.Max(p=>p.X),samples.Max(p=>p.Y)))),low=0;var best=new List<PointF>{samples[0],samples.Last()};for(int i=0;i<22;i++){float tolerance=(low+high)/2;var points=ArcAssist.Simplify(samples,tolerance);if(points.Count<=target){high=tolerance;best=points;}else low=tolerance;}if(best.Count>=Points.Count)return copy;if(Kind=="Line"&&Handles.Count>0)copy.Kind="Curvature pen";copy.Points=best;copy.Points[0]=Points[0];copy.Points[copy.Points.Count-1]=Points.Last();copy.Handles.Clear();return copy;}
}
class SimplifyPreview:Control {
 public List<VectorShape> Original=new List<VectorShape>(),Result=new List<VectorShape>();
 public SimplifyPreview(){DoubleBuffered=true;BackColor=Color.White;}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(Original.Count==0)return;RectangleF bounds=Original[0].Bounds();foreach(var shape in Original.Skip(1))bounds=RectangleF.Union(bounds,shape.Bounds());foreach(var shape in Result)bounds=RectangleF.Union(bounds,shape.Bounds());float scale=Math.Min((Width-40)/Math.Max(1,bounds.Width),(Height-40)/Math.Max(1,bounds.Height));var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.TranslateTransform((Width-bounds.Width*scale)/2,(Height-bounds.Height*scale)/2);g.ScaleTransform(scale,scale);g.TranslateTransform(-bounds.X,-bounds.Y);using(var pen=new Pen(Color.LightGray,3/scale))foreach(var shape in Original)using(var path=shape.Path())g.DrawPath(pen,path);using(var pen=new Pen(Color.Teal,1.5f/scale))foreach(var shape in Result){using(var path=shape.Path())g.DrawPath(pen,path);foreach(var p in shape.Points)g.FillEllipse(Brushes.Teal,p.X-3/scale,p.Y-3/scale,6/scale,6/scale);}}
}
class SimplifyDialog:Form {
 public List<VectorShape> Result;SimplifyPreview preview=new SimplifyPreview();TrackBar amount=new TrackBar{Minimum=10,Maximum=90,Value=50,TickStyle=TickStyle.None};Label count=new Label();List<VectorShape> originals;
 public SimplifyDialog(List<VectorShape> paths){originals=paths.Select(p=>p.Copy()).ToList();Theme.Form(this);Text="Simplify vector paths";ClientSize=new Size(700,500);StartPosition=FormStartPosition.CenterParent;FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=MinimizeBox=false;preview.SetBounds(15,15,670,335);preview.Original=originals;Controls.Add(preview);count.SetBounds(15,360,670,25);Controls.Add(count);amount.SetBounds(15,390,440,35);Controls.Add(amount);Controls.Add(new Label{Text="Grey: original · Teal: rebuilt path and points",Left=15,Top=435,Width=450,Height=25});var apply=Theme.Button("Apply",delegate{DialogResult=DialogResult.OK;});apply.SetBounds(470,445,100,35);Controls.Add(apply);var cancel=Theme.Button("Cancel",delegate{DialogResult=DialogResult.Cancel;});cancel.SetBounds(585,445,100,35);Controls.Add(cancel);AcceptButton=apply;CancelButton=cancel;Theme.Apply(this);preview.BackColor=Color.White;amount.ValueChanged+=delegate{Rebuild();};Rebuild();}
 void Rebuild(){Result=originals.Select(p=>p.Simplified(amount.Value)).ToList();count.Text="Reduction · "+amount.Value+"%    |    Points: "+originals.Sum(p=>p.Points.Count)+" → "+Result.Sum(p=>p.Points.Count);preview.Result=Result;preview.Invalidate();}
}
partial class Canvas {
 public bool CanSimplifySelection{get{return Doc!=null&&Doc.Selected.IsVector&&!Doc.Selected.IsLocked&&selectedPaths.Any(p=>p.CanSimplify);}}
 public List<VectorShape> SimplifyTargets(){return CanSimplifySelection?Doc.Selected.Vectors.Where(p=>selectedPaths.Contains(p)&&p.CanSimplify).ToList():new List<VectorShape>();}
 public void ApplySimplification(List<VectorShape> targets,List<VectorShape> replacements){if(!CanSimplifySelection||targets.Count!=replacements.Count||targets.Any(p=>!Doc.Selected.Vectors.Contains(p)))return;if(!targets.Where((p,i)=>replacements[i].Points.Count<p.Points.Count).Any())return;if(BeforeStroke!=null)BeforeStroke();for(int i=0;i<targets.Count;i++){targets[i].Kind=replacements[i].Kind;targets[i].Points=new List<PointF>(replacements[i].Points);targets[i].Handles=replacements[i].CopyHandles();}selectedPoints.Clear();Doc.Selected.InvalidateVectors();NotifyPointSelection();if(AfterStroke!=null)AfterStroke();Invalidate();}
}
partial class Studio {
 Button simplifyPaths;
 void AddSimplifyButton(FlowLayoutPanel panel){simplifyPaths=Theme.Button("SIMPLIFY",delegate{canvas.EndStroke();var targets=canvas.SimplifyTargets();if(targets.Count==0)return;using(var dialog=new SimplifyDialog(targets))if(dialog.ShowDialog(this)==DialogResult.OK)canvas.ApplySimplification(targets,dialog.Result);canvas.Focus();});simplifyPaths.Width=170;simplifyPaths.TextAlign=ContentAlignment.MiddleCenter;simplifyPaths.Enabled=false;panel.Controls.Add(simplifyPaths);}
 public void TestVersion33(){SetDocument(new Document("A4",100),null);AddTypedLayer(true);var path=new VectorShape{Kind="Curvature pen",Colour=Color.Red,Width=7,Opacity=.6f,Taper=35};for(int i=0;i<40;i++)path.Points.Add(new PointF(50+i*10,150+(float)Math.Sin(i*.13)*40));path.SetPointHandle(10,1,new PointF(170,190));canvas.Doc.Selected.Vectors.Add(path);canvas.SelectPathsInBox(new RectangleF(0,0,600,400),Keys.None);UpdatePointButtons();if(!simplifyPaths.Enabled)throw new Exception("Simplify availability");var low=path.Simplified(10);var high=path.Simplified(80);if(low.Points.Count>=40||high.Points.Count>low.Points.Count||high.Points.Count<2||high.Points.First()!=path.Points.First()||high.Points.Last()!=path.Points.Last()||high.Width!=7||high.Colour!=Color.Red||high.Taper!=35||high.Opacity!=.6f)throw new Exception("Simplify geometry/style");int history=undo.Count;canvas.ApplySimplification(new List<VectorShape>{path},new List<VectorShape>{high});if(undo.Count!=history+1||path.Handles.Count!=0)throw new Exception("Simplify apply");Travel(undo,redo);if(canvas.Doc.Selected.Vectors[0].Points.Count!=40||canvas.Doc.Selected.Vectors[0].Handles.Count!=1)throw new Exception("Simplify undo");Travel(redo,undo);if(canvas.Doc.Selected.Vectors[0].Points.Count!=high.Points.Count)throw new Exception("Simplify redo");canvas.Doc.Selected.Locked=true;if(canvas.CanSimplifySelection)throw new Exception("Locked simplify");using(var dialog=new SimplifyDialog(new List<VectorShape>{low}))if(dialog.Result[0].Points.Count>low.Points.Count)throw new Exception("Dialog rebuild");dirty=false;}
 public void PreviewSimplify(){var path=new VectorShape{Kind="Curvature pen"};for(int i=0;i<50;i++)path.Points.Add(new PointF(10+i*8,100+(float)Math.Sin(i*.12)*50));using(var dialog=new SimplifyDialog(new List<VectorShape>{path})){dialog.Opacity=0;dialog.ShowInTaskbar=false;dialog.Show();using(var b=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"simplify-preview.png"));}}}
}
}
